parameters.inputSchema:
{
  "title": "ExtracaoEntidadesAcademicas",
  "type": "object",
  "description": "Schema para extrair informações sobre professores, departamentos e palavras-chave de pesquisa.",
  "properties": {
    "nome_professor": {
      "type": "string",
      "description": "Nome do professor ou pesquisador extraído da pergunta do usuário."
    },
    "departamento": {
      "type": "string",
      "description": "Departamento acadêmico, instituto ou área de atuação do professor mencionado."
    },
    "palavras_chave": {
      "type": "array",
      "description": "O principal tópico de pesquisa, conceito ou palavra-chave de interesse mencionada pelo usuário.",
      "items": {
        "type": "string"
      }
    }
  }
}

parameters.jsCode:
// Acessa todos os itens que chegam ao nó
const items = $input.all();

// Itera sobre cada item no array de entrada
for (const item of items) {
  // --- Bloco de código original para 'departamento' ---
  if (item.json && item.json.output && item.json.output.departamento) {
    item.json.output.departamento = item.json.output.departamento.normalize("NFD").replace(/[\u0300-\u036f]/g, "");
  }

  // --- NOVO BLOCO DE CÓDIGO PARA 'PALAVRAS_CHAVE' ---
  // Verifica se o campo 'palavras_chave' existe e se é um array
  if (item.json && item.json.output && Array.isArray(item.json.output.palavras_chave)) {
    // Concatena os itens do array em uma única string, separados por espaço
    item.json.output.palavras_chave = item.json.output.palavras_chave.join(' ');
  }
}

// Retorna os itens modificados para o próximo nó
return items;
